<?php require_once __DIR__.'/_base.php'; $title='Provider Profile'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $pid=$pdo->query('SELECT id FROM providers WHERE user_id='.(int)$u['id'])->fetchColumn();$s=$pdo->prepare('SELECT * FROM providers WHERE id=?');$s->execute([$pid]);$p=$s->fetch();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$pdo->prepare('UPDATE providers SET name=?,phone=?,address=?,bio=?,experience=?,charges=? WHERE id=?')->execute([post('name'),post('phone'),post('address'),post('bio'),post('experience'),post('charges'),$pid]);flash('success','Provider profile updated.');redirect('profile.php');}?><div class="service-card p-4 col-lg-8"><h3>Provider Profile</h3><p>Verification: <?=badge($p['verification_status'])?></p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-6"><label class="form-label">Name</label><input name="name" class="form-control" value="<?=e($p['name'])?>"></div><div class="col-md-6"><label class="form-label">Phone</label><input name="phone" class="form-control" value="<?=e($p['phone'])?>"></div><div class="col-12"><label class="form-label">Address</label><input name="address" class="form-control" value="<?=e($p['address'])?>"></div><div class="col-md-6"><label class="form-label">Experience</label><input name="experience" class="form-control" value="<?=e($p['experience'])?>"></div><div class="col-md-6"><label class="form-label">Charges</label><input name="charges" type="number" step=".01" class="form-control" value="<?=e($p['charges'])?>"></div><div class="col-12"><label class="form-label">Bio</label><textarea name="bio" class="form-control" rows="5"><?=e($p['bio'])?></textarea></div><div class="col-12"><button class="btn btn-success">Save</button></div></div></form></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>